'هذه الخطوة لم تعد مطلوبة — يتم اعتماد كل مصادر التمويل تلقائياً عند الاعتماد المالي للمشروع بالكامل' => 'This step is no longer required — all funding sources are approved automatically upon the project\'s full financial approval',
'هذه الخطوة لم تعد مطلوبة — يتم ترحيل القيد المحاسبي تلقائياً عند الاعتماد النهائي من المدير العام' => 'This step is no longer required — the accounting entry is posted automatically upon the General Manager\'s final approval',
'هذه الدفعة أُعيدت من المدير المالي. بعد التعديل ستعود تلقائياً إلى طابور المراجعة، ولن يتم إنشاء قيد محاسبي حتى الاعتماد' => 'This payment was returned by the Financial Manager. After editing, it will automatically return to the review queue, and no accounting entry will be created until approval',
