'هذه الدفعة ما زالت تحتوي على مبالغ غير مستلمة' => 'This payment still contains unreceived amounts',
'هذه الرسالة جماعية ولا يمكن الرد عليها مباشرة من هذه المحادثة' => 'This message is a group message and cannot be replied to directly from this conversation',
'هذه الصفحة تعرض فقط المبالغ التي اعتمدها المحاسب لإعادة تسليمها للأسرة. لا يتم خصم أي مبلغ جديد إلا بعد رفع إيصال التسليم' => 'This page shows only the amounts the accountant approved for re-delivery to the family. No new amount is deducted until the delivery receipt is uploaded',
'هذه الصفحة مخصصة للبيانات العامة. الميزانية والمصروفات والوثائق والتشغيل تُدار من ملف المشروع' => 'This page is for general data. The budget, expenses, documents, and operations are managed from the project file',
'هذه الصفحة هي نقطة تفعيل الأساس المحاسبي للمنظمة. قبل التفعيل يمكنك تحديد سياسة الرسوم الإدارية التي ستستخدمها الحسابات المستقبلية. جميع المبالغ بالنظام بعملة' => 'This page is the activation point of the organization\'s accounting basis. Before activation you can choose the administrative fee policy that future accounts will use. All amounts in the system are in currency',
'هذه العائلة موثقة بالكامل. يمكنك تعديل التوثيق إذا لزم الأمر' => 'This family is fully verified. You can edit the verification if needed',
'هذه العملية تحذف المجموعة نهائياً ولا يمكن التراجع عنها. لا يُسمح بها إلا لأنها لم تُستخدم. هل تريد المتابعة' => 'This operation permanently deletes the group and cannot be undone. It is allowed only because it was never used. Do you want to continue',
'هذه العملية تعني مغادرة دائمة، وليست إجازة مؤقتة. سيتم أرشفة الحساب، وإنهاء التعيينات الحالية للكفلاء، وإظهار الكفلاء غير المعيّنين في قائمة إعادة التوزيع. لن يتم حذف السجل التاريخي للمشرف' => 'This operation means a permanent departure, not a temporary leave. The account will be archived, the sponsors\' current assignments ended, and unassigned sponsors shown in the redistribution list. The supervisor\'s historical record will not be deleted',
