'لا يوجد رصيد قائم صالح لإنشاء جدول السداد.' => 'There is no valid outstanding balance for creating a repayment schedule.',
'يتم اختيار آخر راتب تاريخي صالح لنهاية الشهر. عند إنشاء مسير جديد يتم ربطه بسياسة الرواتب السارية لنهاية الفترة. خصم سلفة الراتب يُحتسب آلياً من جدول السداد ولا يدخل في خانة الخصومات العامة. العملة النظامية:' => 'The latest valid historical salary at month-end is selected. A new payroll run is linked to the payroll policy effective at period end. Salary-advance deductions are calculated automatically from the repayment schedule and are not included in general deductions. System currency:',
'سياسة سنوية/مُصدرة من FM وتستخدم كإعدادات افتراضية لطلبات السلف. يمكن تخصيص الشروط لاحقاً لكل طلب دون تعديل السياسة الأصلية.' => 'An annual policy issued by the FM and used as default settings for salary-advance requests. Conditions can later be customized per request without changing the original policy.',
'مسار موحد لمعالجة الطلب من مراجعة FM، إلى التحقق المحاسبي، ثم الصرف وإنشاء جدول السداد — دون الانتقال بين صفحات معالجة مختلفة.' => 'A unified workflow for processing the request from FM review, through accounting verification, to disbursement and repayment-schedule creation — without moving between separate processing pages.',
'لا يوجد اعتماد محاسبي منفصل. عند اختيار «صرف وترحيل» سيتم اعتماد التحقق المحاسبي وترحيل قيد الصرف داخل عملية محاسبية واحدة؛ لذلك لا يمكن ترك الطلب في حالة «تم التحقق» دون صرف.' => 'There is no separate accounting approval. When “Disburse and post” is selected, accounting verification is approved and the disbursement entry is posted within one accounting transaction; therefore the request cannot remain in “Verified” status without disbursement.',
'سبب الرفض المحاسبي' => 'Accounting rejection reason',
'التحقق المحاسبي والصرف يتمان معاً داخل معاملة واحدة. عند نجاح هذه العملية لا يمكن أن يبقى الطلب في حالة «تم التحقق» دون أن يصبح «تم الصرف».' => 'Accounting verification and disbursement are performed together in one transaction. When successful, the request cannot remain in “Verified” status without becoming “Disbursed”.',
'يجب تسوية السلفة السابقة أولاً.' => 'The previous salary advance must be settled first.',
'تم إرسال المشروع لدورة الاعتماد؛ الميزانية الأولية للعرض فقط. يمكن تعديلها قبل الإرسال للمدير المالي أو بعد الإرجاع للمراجعة.' => 'The project was submitted for the approval cycle; the initial budget is for display only. It can be edited before submission to the Financial Manager or after it is returned for review.',
'العملة ثابتة على الجنيه السوداني (SDG)، ويجب أن يساوي إجمالي بنود الميزانية الإجمالي المطلوب (الميزانية التقديرية + الرسوم الحكومية) تماماً.' => 'The currency is fixed to Sudanese Pound (SDG), and the total budget items must exactly equal the total requirement (estimated budget + government fees).',
'✓ إجمالي بنود الميزانية يساوي الإجمالي المطلوب (الميزانية التقديرية + الرسوم الحكومية) تماماً. يمكن حفظ المشروع.' => '✓ The total budget items exactly equals the total requirement (estimated budget + government fees). The project can be saved.',
'لا يمكن حفظ المشروع. يجب أن يساوي إجمالي بنود الميزانية الإجمالي المطلوب (الميزانية التقديرية + الرسوم الحكومية) تماماً.' => 'The project cannot be saved. The total budget items must exactly equal the total requirement (estimated budget + government fees).',
