'الحالة المخططة وقيد التنفيذ لا تُغيّران من مسار مشرف المشروع؛ الإطلاق يتم حصراً من مدير المشاريع.' => 'Planned and active status cannot be changed by the Project Supervisor; launch is performed exclusively by the Projects Manager.',
'إدخال مصروفات المشروع يتم مباشرة بواسطة مشرف المشروع من ميزانية المشروع المحوّلة إليه، ولا يتم استخدام حسابات المنظمة لهذا المسار.' => 'Project expenses are entered directly by the Project Supervisor from the project budget transferred to them; organization accounts are not used for this workflow.',
'تم الإفراج عن تمويل المشروع تحت سيطرة مشرف المشروع. لا يجوز ترحيل مصروف تنفيذي بقيد خزينة ثانٍ؛ سجّل الدفعة من خلال مصروفات التنفيذ الخاصة بالمشروع.' => 'Project funding has been released under the Project Supervisor’s control. An execution expense must not be posted through a second treasury entry; record the payment through the project’s execution expenses.',
'مشرف المشروع لا ينفذ الإغلاق مباشرة. أرسل الطلب إلى مدير المشاريع مع الملاحظات ليقوم بالمراجعة والتنفيذ.' => 'The Project Supervisor does not execute closure directly. Send the request to the Projects Manager with notes for review and execution.',
'لم يسجل المدير المالي تسوية الرصيد المتبقي بعد. سيتم تحويل المشروع بعد إغلاقه إدارياً إلى المدير المالي لإتمام الإغلاق المالي وإرجاع الرصيد المتبقي.' => 'The Financial Manager has not yet recorded the settlement of the remaining balance. After administrative closure, the project will be transferred to the Financial Manager to complete financial closure and return the remaining balance.',
